import { useEffect, useState } from 'react';

// Loads public/events.json (generated by scripts/fetch-events.mjs) and keeps only today's and future events.
// Returns null while loading, then an array (possibly empty).
const useUpcomingEvents = () => {
  const [events, setEvents] = useState(null);

  useEffect(() => {
    fetch('events.json')
      .then((r) => (r.ok ? r.json() : []))
      .then((all) =>
        setEvents(all.filter((e) => new Date(e.date) >= new Date().setHours(0, 0, 0, 0)))
      )
      .catch(() => setEvents([]));
  }, []);

  return events;
};

export default useUpcomingEvents;
